let dataStamp = 'MAG Heat Relief Network · 2026 season snapshot';

const CATEGORIES = {
  /* Category is carried by the glyph (see ICONS); colour only has to keep the
     four apart at 24px in daylight. Hues are spaced >=48 deg with distinct
     lightness, and every fill clears 4.9:1 against its white glyph. The old
     set put Cooling and Hydration 5.6 deg apart — the two most common pins —
     and gave Respite an emergency red. */
  cool: { label: 'Cooling center',    raw: '#0f766e', short: 'Cooling' },   /* teal   175 deg */
  hydr: { label: 'Hydration station', raw: '#1d4ed8', short: 'Hydration' }, /* blue   224 deg */
  resp: { label: 'Respite center',    raw: '#9d174d', short: 'Respite' },   /* rose   336 deg */
  coll: { label: 'Donation drop-off', raw: '#4d7c0f', short: 'Donations' }  /* moss    86 deg */
};

const SERVICES = {
  food:     { label: 'Food' },
  shower:   { label: 'Showers' },
  health:   { label: 'Health services' },
  homeless: { label: 'Homeless services' },
  hygiene:  { label: 'Hygiene items' },
  clothing: { label: 'Clothing' },
  laundry:  { label: 'Laundry' },
  utility:  { label: 'Utility help' }
};

/* Category glyphs, by name from the shared icon set (js/icons.js). pinIcon()
   draws them inside the teardrop; the 24x24 geometry is scaled as a whole, so
   a pin glyph carries the same stroke ratio as every other icon in the app. */
const ICONS = {
  cool: 'snowflake',
  hydr: 'droplet',
  resp: 'house',
  coll: 'package'
};

const _DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const _TYPE = { 'Cooling Center': 'cool', 'Hydration Station': 'hydr', 'Respite Center': 'resp' };
const _SVC = { 'food': 'food', 'showers': 'shower', 'health services': 'health',
               'homeless services': 'homeless', 'hygiene items': 'hygiene',
               'clothing': 'clothing', 'laundry': 'laundry', 'utility assistance': 'utility' };

function _mins(v) {
  const m = /^\s*(\d{1,2}):(\d{2})\s*(AM|PM)\s*$/i.exec(v || '');
  if (!m) return null;
  let h = +m[1] % 12;
  if (m[3].toUpperCase() === 'PM') h += 12;
  return h * 60 + +m[2];
}
function _iso(v) { return v ? new Date(v).toISOString().slice(0, 10) : null; }
function _yn(v) { v = (v || '').trim().toLowerCase(); return v === 'yes' ? 1 : v === 'no' ? 0 : null; }

function toSite(f) {
  const p = f.properties || {};
  if (!f.geometry || !f.geometry.coordinates) return null;
  const cats = [];
  const t = _TYPE[(p.HeatRelief_Type || '').trim()];
  if ((p.HeatRelief || '').toLowerCase() === 'yes' && t) cats.push(t);
  if ((p.Collection || '').toLowerCase() === 'yes' && p.Collection_Type) cats.push('coll');
  if (!cats.length) return null;

  const hr = _DAYS.map(d => {
    const o = _mins(p[d + 'Open']), c = _mins(p[d + 'Close']);
    return (o != null && c != null) ? [o, c] : null;
  });
  const hol = {};
  [['MemorialDay','memorial'],['Juneteenth','juneteenth'],
   ['IndependenceDay','july4'],['LaborDay','labor']].forEach(([k, key]) => {
    if (p[k]) hol[key] = String(p[k]).trim();
  });
  const sv = [];
  (p.Services || '').split(',').forEach(s => {
    const k = _SVC[s.trim().toLowerCase()];
    if (k && sv.indexOf(k) < 0) sv.push(k);
  });

  return {
    n: (p.Location || p.Organization || 'Heat relief site').trim(),
    o: p.Organization ? p.Organization.trim() : null,
    a: p.Address ? p.Address.trim() : null,
    ci: p.City ? p.City.trim() : null,
    ph: p.PrimaryPhone ? p.PrimaryPhone.trim() : null,
    c: cats, ct: p.Collection_Type || null, hs: p.Hours || null, hr: hr,
    hol: Object.keys(hol).length ? hol : null, sv: sv.length ? sv : null,
    wc: _yn(p.Wheelchair_access), ada: _yn(p.ADA_accessible), pet: _yn(p.Pets),
    nt: p.Note || null, sd: _iso(p.Start_Date), ed: _iso(p.End_Date),
    ll: [f.geometry.coordinates[1], f.geometry.coordinates[0]],
    ml: p.map_link || null
  };
}

